  try {
    const output = execSync(`docker ${cmd}`, { encoding: 'utf8', stdio: ['pipe', 'pipe', 'pipe'] });
    return output.trim();
  } catch (err) {
    return err.stderr ? err.stderr.toString().trim() : err.message;
  }
}

